  if (await mic.count()) { await mic.click(); log('mic toggled, pressed=', await mic.getAttribute('aria-pressed')); }
  await sleep(25000); await shot('after-mic');
  log('main text:', (await page.locator('body').innerText()).replace(/\s+/g,' ').slice(0, 900));
  const input = page.getByPlaceholder('Or type here…');
  if (await input.count() && await input.isEnabled()) { await input.fill('My cat Mimi is limping after she jumped off the wardrobe. Please find a vet.'); await input.press('Enter'); log('typed'); }
  await sleep(20000); await shot('after-text');
  log('main text:', (await page.locator('body').innerText()).replace(/\s+/g,' ').slice(0, 1500));
  const plan = page.getByRole('button', { name: /clinic|vet|plan|continue|next/i });
  log('candidate buttons:', await page.getByRole('button').allInnerTexts());
  if (process.env.PHASE2) {
    await page.getByRole('button', { name: 'Prepare' }).first().click(); log('clicked Prepare (vet)');
    await sleep(12000); await shot('clinics');
    log('clinics text:', (await page.locator('body').innerText()).replace(/\s+/g,' ').slice(0, 1200));
    log('buttons:', JSON.stringify(await page.getByRole('button').allInnerTexts()).slice(0,800));
    const pick = page.locator('article.clinic button').first();
    if (await pick.count()) { await pick.click(); log('picked first clinic'); await sleep(15000); await shot('handoff');
      log('handoff text:', (await page.locator('body').innerText()).replace(/\s+/g,' ').slice(0, 1500));
      log('buttons:', JSON.stringify(await page.getByRole('button').allInnerTexts()).slice(0,800)); }
  }
} catch (e) { log('SCRIPT ERROR', e.message); await shot('error').catch(()=>{}); }
log('CONSOLE/ERRORS (' + errors.length + '):'); for (const e of errors.slice(0,40)) console.log('  ', e.slice(0,300));
await browser.close();
